#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct RandomState {
    pub seed: u8,
}

/// Deterministically maps `state.seed` to one of eight values in [0, 1):
/// 0.0, 0.125, 0.25, 0.375, 0.5, 0.625, 0.75, 0.875.
pub fn random(state: RandomState) -> f32 {
    // seed % 8, but using a bitmask since 8 is a power of two.
    let k: u8 = state.seed & 7;
    (k as f32) * 0.125_f32
}

